import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_HW": 4096, "warp_size": 32}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_HW": 8192, "warp_size": 32}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_HW": 16384, "warp_size": 32}, num_warps=16, num_stages=2),
        triton.Config({"BLOCK_HW": 8192, "warp_size": 16}, num_warps=16, num_stages=2),
        triton.Config({"BLOCK_HW": 16384, "warp_size": 16}, num_warps=16, num_stages=3),
    ],
    key=["HW", "channels_per_group"],
)
@triton.jit
def group_norm_stats_kernel(
    x_ptr,
    mean_ptr,
    invstd_ptr,
    C: tl.constexpr,
    HW: tl.constexpr,
    num_groups: tl.constexpr,
    eps: tl.constexpr,
    channels_per_group: tl.constexpr,
    BLOCK_HW: tl.constexpr,
    warp_size: tl.constexpr,
):
    pid = tl.program_id(0)
    batch_idx = pid // num_groups
    group_idx = pid % num_groups

    channel_start = group_idx * channels_per_group
    batch_offset = batch_idx.to(tl.int64) * C * HW
    group_elems = channels_per_group * HW

    sum_val = 0.0
    sq_val = 0.0

    for c in range(channels_per_group):
        c_offset = (channel_start + c).to(tl.int64) * HW
        base = batch_offset + c_offset
        for hw_start in range(0, HW, BLOCK_HW):
            offs = hw_start + tl.arange(0, BLOCK_HW)
            mask = offs < HW
            x_val = tl.load(x_ptr + base + offs.to(tl.int64), mask=mask, other=0.0).to(
                tl.float32
            )
            sum_val += tl.sum(x_val, axis=0)
            sq_val += tl.sum(x_val * x_val, axis=0)

    mean = sum_val / group_elems
    variance = sq_val / group_elems - mean * mean
    inv_std = 1.0 / tl.sqrt(variance + eps)

    tl.store(mean_ptr + pid, mean)
    tl.store(invstd_ptr + pid, inv_std)


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_HW": 4096, "warp_size": 32}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_HW": 8192, "warp_size": 32}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_HW": 16384, "warp_size": 32}, num_warps=16, num_stages=2),
        triton.Config({"BLOCK_HW": 8192, "warp_size": 16}, num_warps=16, num_stages=2),
        triton.Config({"BLOCK_HW": 16384, "warp_size": 16}, num_warps=16, num_stages=3),
    ],
    key=["HW"],
)
@triton.jit
def group_norm_apply_kernel(
    x_ptr,
    y_ptr,
    mean_ptr,
    invstd_ptr,
    weight_ptr,
    bias_ptr,
    C: tl.constexpr,
    HW: tl.constexpr,
    num_groups: tl.constexpr,
    channels_per_group: tl.constexpr,
    BLOCK_HW: tl.constexpr,
    warp_size: tl.constexpr,
):
    pid = tl.program_id(0)
    batch_idx = pid // C
    channel_idx = pid % C
    group_idx = channel_idx // channels_per_group

    stats_idx = batch_idx * num_groups + group_idx
    mean = tl.load(mean_ptr + stats_idx)
    inv_std = tl.load(invstd_ptr + stats_idx)
    w = tl.load(weight_ptr + channel_idx).to(tl.float32)
    b = tl.load(bias_ptr + channel_idx).to(tl.float32)

    scale = inv_std * w
    shift = b - mean * scale

    batch_offset = batch_idx.to(tl.int64) * C * HW
    c_offset = channel_idx.to(tl.int64) * HW
    base = batch_offset + c_offset

    for hw_start in range(0, HW, BLOCK_HW):
        offs = hw_start + tl.arange(0, BLOCK_HW)
        mask = offs < HW
        x_val = tl.load(x_ptr + base + offs.to(tl.int64), mask=mask, other=0.0).to(
            tl.float32
        )
        normed = x_val * scale + shift
        tl.store(y_ptr + base + offs.to(tl.int64), normed.to(tl.bfloat16), mask=mask)


class Model(nn.Module):
    def __init__(self, num_features: int, num_groups: int):
        super(Model, self).__init__()
        self.gn = nn.GroupNorm(num_groups=num_groups, num_channels=num_features)
        self.num_features = num_features
        self.num_groups = num_groups
        self._packed = False

    def _pack_weights(self, device):
        self.weight_packed = self.gn.weight.data.to(device).contiguous()
        self.bias_packed = self.gn.bias.data.to(device).contiguous()
        self._packed = True

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        device = x.device
        x = x.contiguous()
        if not self._packed:
            self._pack_weights(device)

        N, C, H, W_dim = x.shape
        HW = H * W_dim
        channels_per_group = C // self.num_groups
        y = torch.empty_like(x)
        eps = self.gn.eps

        mean_buf = torch.empty(N * self.num_groups, device=device, dtype=torch.float32)
        invstd_buf = torch.empty(
            N * self.num_groups, device=device, dtype=torch.float32
        )

        stats_grid = (N * self.num_groups,)
        group_norm_stats_kernel[stats_grid](
            x,
            mean_buf,
            invstd_buf,
            C,
            HW,
            self.num_groups,
            eps,
            channels_per_group,
        )

        apply_grid = (N * C,)
        group_norm_apply_kernel[apply_grid](
            x,
            y,
            mean_buf,
            invstd_buf,
            self.weight_packed,
            self.bias_packed,
            C,
            HW,
            self.num_groups,
            channels_per_group,
        )
        return y
